//! Guest layout of Sonic's speed context and posture: byte offsets (used to marshal
//! state for the xenon-oracle tests and to decode traces) and flag indices.
//! Generated by sheets/sheetc.py from sheets/context_fields.csv and
//! context_flags.csv: edit the sheets, not this file.

pub mod offset {
    pub mod posture {
        /// ptr: Its speed context.
        pub const CONTEXT: u32 = 0x008;
        /// ptr: Frame timing (+0x24: dt).
        pub const TIMING: u32 = 0x00C;
    }
    pub mod speed_context {
        /// ptr: Body object (vf2 -> its matrix; +0x60 its rotation).
        pub const BODY: u32 = 0x010;
        /// ptr: Not identified yet.
        pub const FIELD_0X104: u32 = 0x104;
        /// vec4: World-space stick direction.
        pub const STICK: u32 = 0x120;
        /// ptr: Parameter store tree for this character.
        pub const PARAM_STORE: u32 = 0x1FC;
        /// vec4: World velocity.
        pub const VELOCITY: u32 = 0x210;
        /// vec4: Velocity in the ground plane.
        pub const HORIZONTAL_VELOCITY: u32 = 0x220;
        /// vec4: Velocity along the ground normal.
        pub const VERTICAL_VELOCITY: u32 = 0x230;
        /// vec4: Not identified yet.
        pub const FIELD_0X240: u32 = 0x240;
        /// mat4: World to ground-frame rotation.
        pub const TO_LOCAL: u32 = 0x250;
        /// mat4: Ground frame back to world.
        pub const TO_WORLD: u32 = 0x290;
        /// u8: Not identified yet.
        pub const FIELD_0X2E0: u32 = 0x2E0;
        /// vec4: Up vector (velocity turns about it).
        pub const UP: u32 = 0x2F0;
        /// vec4: Not identified yet.
        pub const FIELD_0X300: u32 = 0x300;
        /// vec4: Not identified yet.
        pub const FIELD_0X310: u32 = 0x310;
        /// vec4: Not identified yet.
        pub const FIELD_0X320: u32 = 0x320;
        /// vec4: Not identified yet.
        pub const FIELD_0X330: u32 = 0x330;
        /// u8: On the ground.
        pub const GROUNDED: u32 = 0x3C0;
        /// vec4: Not identified yet.
        pub const FIELD_0X3D0: u32 = 0x3D0;
        /// quat: Current rotation.
        pub const ROTATION: u32 = 0x440;
        /// quat: Rotation set this frame.
        pub const TARGET_ROTATION: u32 = 0x460;
        /// vec4: Not identified yet.
        pub const FIELD_0X470: u32 = 0x470;
        /// ptr: Flag set (+4 -> byte per flag; sheets/context_flags.csv).
        pub const FLAGS: u32 = 0x4AC;
        /// ptr: Second flag set.
        pub const FLAGS2: u32 = 0x4B0;
        /// u8: Selects the 2D SideView parameters (sub_82317508).
        pub const SIDE_VIEW: u32 = 0x4B4;
        /// f32: Divisor of the deceleration fallback.
        pub const FALLBACK_DIV: u32 = 0x4B8;
        /// f32: Not identified yet.
        pub const FIELD_0X4E4: u32 = 0x4E4;
        /// f32: Not identified yet.
        pub const FIELD_0X50C: u32 = 0x50C;
        /// f32: Blend toward the fixed rotation force under flag 22.
        pub const ROTATION_BLEND: u32 = 0x510;
        /// f32: Scale of the deceleration fallback.
        pub const FALLBACK_SCALE: u32 = 0x540;
        /// f32: Time since the stick changed (NoPadStopWalk).
        pub const STICK_TIMER: u32 = 0x54C;
        /// f32: Scale on turning input and velocity changes.
        pub const INPUT_SCALE: u32 = 0x554;
        /// u8: Horizontal/vertical split needs recomputing.
        pub const SPLIT_STALE: u32 = 0x565;
        /// u8: World velocity needs rebuilding from the split.
        pub const VELOCITY_DIRTY: u32 = 0x566;
        /// f32: Not identified yet.
        pub const FIELD_0X580: u32 = 0x580;
        /// f32: Not identified yet.
        pub const FIELD_0X584: u32 = 0x584;
        /// vec4: Not identified yet.
        pub const FIELD_0X5F0: u32 = 0x5F0;
        /// ptr: KeepRunning guide object.
        pub const KEEP_RUNNING_GUIDE: u32 = 0x650;
        /// u8: Guide direction already points forward.
        pub const GUIDE_FORWARD: u32 = 0x658;
        /// vec4: Direction a reversed surface normal is checked against for landing (normalized on use).
        pub const LANDING_REFERENCE: u32 = 0x6A0;
        /// vec4: Contact normal velocity changes may not push into.
        pub const CONTACT_NORMAL: u32 = 0x6B0;
        /// ptr: Not identified yet.
        pub const FIELD_0XC94: u32 = 0xC94;
        /// u8: Not identified yet.
        pub const FIELD_0XC98: u32 = 0xC98;
        /// vec4: Not identified yet.
        pub const FIELD_0XCA0: u32 = 0xCA0;
        /// vec4: Not identified yet.
        pub const FIELD_0XCB0: u32 = 0xCB0;
        /// i32: Enemies blocking Sonic.
        pub const BLOCKED_COUNT: u32 = 0xCC8;
        /// f32: Accumulated sideways stick input.
        pub const LEAN_INPUT: u32 = 0xD3C;
    }
}

/// Index of each flag in the flag set at speed_context+0x4AC.
pub mod flag {
    /// No turning or velocity changes.
    pub const FROZEN: u32 = 3;
    /// Boost.
    pub const BOOSTING: u32 = 14;
    /// Blend the rotation force toward a fixed value.
    pub const ROTATION_FORCE_BLEND: u32 = 22;
    /// NoPadStopWalk.
    pub const NO_PAD_STOP_WALK: u32 = 26;
    /// KeepRunning.
    pub const KEEP_RUNNING: u32 = 31;
    /// Facing is not turned.
    pub const KEEP_FACING: u32 = 37;
}
